18.10 検定統計量とP値
検定統計量 \(t\) と臨界値を比べる代わりに、P値（P-value）と有意水準を比べる方法もあります。

P値

帰無仮説が正しいと仮定したときに、実際に計算した \(t\) 値と同じか、それよりも極端な値が得られる確率です。
両側検定の場合は、分布の \(-|t|\) より左側と、\(|t|\) より右側の面積を合計したものになります（下の図の斜線部分）。

判断の方法

P値が有意水準より小さい（P値 &lt; 有意水準）ならば、帰無仮説を棄却します。
P値が有意水準以上ならば、帰無仮説を棄却しません。

臨界値との関係

「\(|t|\) が臨界値より大きい」ことと、「P値が有意水準より小さい」ことは、同じことを表しています。
\(t\) が棄却域の中にあれば、\(t\) より外側の面積（P値）は、棄却域の面積（有意水準）より小さくなるためです。











図 18.10




「具体的な計算」の例で確かめてみましょう
\(n = 4\)（自由度3）で \(t = 4\) だった例について、P値の部分を塗ったのが下の図です。オレンジの斜線部分の面積がP値、点線は有意水準5%の臨界値です。自由度や \(t\) 値を変えて、P値や臨界値がどう変わるかも確かめてみましょう。


コードを表示
viewof dfP = Inputs.select([1, 2, 3, 5, 10, 30, 100], {value: 3, label: "自由度"})
viewof tP = Inputs.range([0, 6], {step: 0.1, value: 4, label: "t 値"})


















コードを表示
tTools = {
  // 対数ガンマ関数（Lanczos近似）
  function lgamma(z) {
    const g = 7;
    const c = [0.99999999999980993, 676.5203681218851, -1259.1392167224028,
      771.32342877765313, -176.61502916214059, 12.507343278686905,
      -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
    if (z &lt; 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - lgamma(1 - z);
    z -= 1;
    let x = c[0];
    for (let i = 1; i &lt; g + 2; i++) x += c[i] / (z + i);
    const t = z + g + 0.5;
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  }
  // 不完全ベータ関数（連分数展開）
  function betacf(a, b, x) {
    const FPMIN = 1e-300;
    let qab = a + b, qap = a + 1, qam = a - 1, c = 1, d = 1 - qab * x / qap;
    if (Math.abs(d) &lt; FPMIN) d = FPMIN;
    d = 1 / d;
    let h = d;
    for (let m = 1; m &lt;= 200; m++) {
      const m2 = 2 * m;
      let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
      d = 1 + aa * d; if (Math.abs(d) &lt; FPMIN) d = FPMIN;
      c = 1 + aa / c; if (Math.abs(c) &lt; FPMIN) c = FPMIN;
      d = 1 / d; h *= d * c;
      aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
      d = 1 + aa * d; if (Math.abs(d) &lt; FPMIN) d = FPMIN;
      c = 1 + aa / c; if (Math.abs(c) &lt; FPMIN) c = FPMIN;
      d = 1 / d;
      const del = d * c;
      h *= del;
      if (Math.abs(del - 1) &lt; 1e-14) break;
    }
    return h;
  }
  function ibeta(x, a, b) {
    if (x &lt;= 0) return 0;
    if (x &gt;= 1) return 1;
    const bt = Math.exp(lgamma(a + b) - lgamma(a) - lgamma(b) + a * Math.log(x) + b * Math.log(1 - x));
    return x &lt; (a + 1) / (a + b + 2) ? bt * betacf(a, b, x) / a : 1 - bt * betacf(b, a, 1 - x) / b;
  }
  // t分布の確率密度
  const pdf = (x, v) =&gt;
    Math.exp(lgamma((v + 1) / 2) - lgamma(v / 2)) / Math.sqrt(v * Math.PI) *
    Math.pow(1 + x * x / v, -(v + 1) / 2);
  // 両側P値
  const p2 = (t, v) =&gt; ibeta(v / (v + t * t), v / 2, 0.5);
  // 両側検定の臨界値（二分法）
  const crit = (alpha, v) =&gt; {
    let lo = 0, hi = 100;
    for (let i = 0; i &lt; 100; i++) {
      const m = (lo + hi) / 2;
      if (p2(m, v) &gt; alpha) lo = m; else hi = m;
    }
    return (lo + hi) / 2;
  };
  return {pdf, p2, crit};
}

pValue = tTools.p2(tP, dfP)
tCrit = tTools.crit(0.05, dfP)

md`自由度 ${dfP}　t = ${tP.toFixed(1)}　**P値（両側）= ${pValue.toFixed(3)}**　臨界値（両側・5%）= ±${tCrit.toFixed(3)}　→　${pValue &lt; 0.05 ? "有意水準5%で帰無仮説を**棄却します**" : "有意水準5%で帰無仮説を**棄却しません**"}`






























コードを表示
{
  const xs = d3.range(-6, 6.001, 0.02);
  const curve = xs.map(x =&gt; ({x: x, y: tTools.pdf(x, dfP)}));
  const right = curve.filter(d =&gt; d.x &gt;= tP);
  const left = curve.filter(d =&gt; d.x &lt;= -tP);
  return Plot.plot({
    x: {domain: [-6, 6], label: "t"},
    y: {domain: [0, 0.42], label: "確率密度", grid: true},
    marks: [
      Plot.areaY(right, {x: "x", y: "y", fill: "#E36C09", fillOpacity: 0.5}),
      Plot.areaY(left, {x: "x", y: "y", fill: "#E36C09", fillOpacity: 0.5}),
      Plot.line(curve, {x: "x", y: "y", stroke: "steelblue", strokeWidth: 2.5}),
      Plot.ruleX([-tCrit, tCrit], {stroke: "black", strokeWidth: 1.5, strokeDasharray: "4,3"}),
      Plot.ruleX([-tP, tP], {stroke: "#E36C09", strokeWidth: 2}),
      Plot.text([{x: tP, label: `t = ${tP.toFixed(1)}`}], {x: "x", y: 0.4, text: "label", fill: "#E36C09", fontSize: 13, dx: 6, textAnchor: "start"}),
      Plot.ruleY([0])
    ]
  });
}















NoteP値の読み方の注意




P値は「帰無仮説が正しい確率」ではありません。「帰無仮説が正しいとしたら、今回のようなデータ（またはそれより極端なデータ）がどのくらいの確率で得られるか」を表す値です。
P値が小さいほど、「帰無仮説が正しいとすると、今回のデータはとても珍しい」ということになり、帰無仮説を疑う根拠が強くなります。
統計ソフトやエクセルの分析ツールでは、多くの場合、臨界値ではなくP値が出力されます。

21.4 カイ二乗分布
カイ二乗分布は、自由度によって形が変わります。自由度と \(\chi^2\) の値を変えて、分布の形、臨界値（有意水準5%）、P値がどう変わるかを確かめてみましょう。初期値は、例1の \(\chi^2 = 0.641\)（自由度1）です。


コードを表示
viewof dfC = Inputs.select([1, 2, 3, 4, 5, 10], {value: 1, label: "自由度"})
viewof chiC = Inputs.range([0, 20], {step: 0.01, value: 0.641, label: "χ² の値"})


















コードを表示
chiTools = {
  // 対数ガンマ関数（Lanczos近似）
  function lgamma(z) {
    const g = 7;
    const c = [0.99999999999980993, 676.5203681218851, -1259.1392167224028,
      771.32342877765313, -176.61502916214059, 12.507343278686905,
      -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
    if (z &lt; 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - lgamma(1 - z);
    z -= 1;
    let x = c[0];
    for (let i = 1; i &lt; g + 2; i++) x += c[i] / (z + i);
    const t = z + g + 0.5;
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  }
  // 正則化不完全ガンマ関数 P(a, x)
  function gammaP(a, x) {
    if (x &lt;= 0) return 0;
    if (x &lt; a + 1) {
      let sum = 1 / a, del = sum, ap = a;
      for (let n = 1; n &lt; 500; n++) {
        ap += 1; del *= x / ap; sum += del;
        if (Math.abs(del) &lt; Math.abs(sum) * 1e-15) break;
      }
      return sum * Math.exp(-x + a * Math.log(x) - lgamma(a));
    }
    let b = x + 1 - a, c = 1e300, d = 1 / b, h = d;
    for (let i = 1; i &lt; 500; i++) {
      const an = -i * (i - a);
      b += 2;
      d = an * d + b; if (Math.abs(d) &lt; 1e-300) d = 1e-300;
      c = b + an / c; if (Math.abs(c) &lt; 1e-300) c = 1e-300;
      d = 1 / d;
      const del = d * c;
      h *= del;
      if (Math.abs(del - 1) &lt; 1e-15) break;
    }
    return 1 - Math.exp(-x + a * Math.log(x) - lgamma(a)) * h;
  }
  // カイ二乗分布の確率密度
  const pdf = (x, k) =&gt;
    x &lt;= 0 ? 0 : Math.exp((k / 2 - 1) * Math.log(x) - x / 2 - (k / 2) * Math.log(2) - lgamma(k / 2));
  // 右側の確率（P値）
  const upper = (x, k) =&gt; 1 - gammaP(k / 2, x / 2);
  // 臨界値（二分法）
  const crit = (alpha, k) =&gt; {
    let lo = 0, hi = 200;
    for (let i = 0; i &lt; 100; i++) {
      const m = (lo + hi) / 2;
      if (upper(m, k) &gt; alpha) lo = m; else hi = m;
    }
    return (lo + hi) / 2;
  };
  return {pdf, upper, crit};
}

pChi = chiTools.upper(chiC, dfC)
critChi = chiTools.crit(0.05, dfC)

md`自由度 ${dfC}　χ² = ${chiC.toFixed(3)}　**P値 = ${pChi.toFixed(3)}**　臨界値（5%）= ${critChi.toFixed(3)}　→　${pChi &lt; 0.05 ? "有意水準5%で帰無仮説を**棄却します**" : "有意水準5%で帰無仮説を**棄却しません**"}`






























コードを表示
{
  const xs = d3.range(0.02, 20.001, 0.02);
  const curve = xs.map(x =&gt; ({x: x, y: chiTools.pdf(x, dfC)}));
  const tail = curve.filter(d =&gt; d.x &gt;= chiC);
  return Plot.plot({
    x: {domain: [0, 20], label: "χ²"},
    y: {domain: [0, 0.6], label: "確率密度", grid: true},
    marks: [
      Plot.areaY(tail, {x: "x", y: "y", fill: "#E36C09", fillOpacity: 0.5, clip: true}),
      Plot.line(curve, {x: "x", y: "y", stroke: "steelblue", strokeWidth: 2.5, clip: true}),
      Plot.ruleX([critChi], {stroke: "black", strokeWidth: 1.5, strokeDasharray: "4,3"}),
      Plot.ruleX([chiC], {stroke: "#E36C09", strokeWidth: 2}),
      Plot.ruleY([0])
    ]
  });
}









オレンジの部分の面積がP値、黒の点線が有意水準5%の臨界値です。カイ二乗分布についての詳しい説明は、カイ二乗分布（統計学の時間）も参考にしてください。

22.11 標本によって回帰係数が変わる様子
母集団の回帰式が \(y = 90 + 2x + \varepsilon\)（\(\varepsilon\) の標準偏差は32）であるとして、ビールのデータと同じ12個の気温で、何度も標本を取り直してみます。母集団の傾きは \(\beta = 2\) ですが、標本から計算した \(b\) は、標本ごとに変わります。


コードを表示
viewof nDraw = Inputs.select(new Map([["1回", 1], ["10回", 10], ["100回", 100]]), {value: 1, label: "取り直す回数"})
viewof goB = Inputs.button("標本を取り直す")


















コードを表示
mutable bList = []

simSample = {
  goB;
  const xs = beer.map(d =&gt; d.x);
  const alpha = 90, beta = 2, sigma = 32;
  const randn = () =&gt; {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const fit = pts =&gt; {
    const n = pts.length;
    const mx = d3.mean(pts, d =&gt; d.x), my = d3.mean(pts, d =&gt; d.y);
    const sxx = d3.sum(pts, d =&gt; (d.x - mx) ** 2);
    const sxy = d3.sum(pts, d =&gt; (d.x - mx) * (d.y - my));
    const b = sxy / sxx, a = my - b * mx;
    const sse = d3.sum(pts, d =&gt; (d.y - a - b * d.x) ** 2);
    const se = Math.sqrt(sse / (n - 2) / sxx);
    return {a, b, se, t: b / se};
  };
  let last = null;
  const newFits = [];
  for (let k = 0; k &lt; nDraw; k++) {
    const pts = xs.map(x =&gt; ({x: x, y: alpha + beta * x + sigma * randn()}));
    const f = fit(pts);
    newFits.push(f);
    last = {pts, ...f};
  }
  mutable bList = mutable bList.concat(newFits);
  return last;
}

sigShare = d3.mean(bList, d =&gt; Math.abs(d.t) &gt; 2.228 ? 1 : 0)

