23.7 係数が変わる仕組みを確かめよう
出席率と学習時間の相関の強さを変えて、100人分のデータを作り、単回帰分析と重回帰分析の出席率の係数を比べてみましょう。データは、「本当の関係」を \(\text{成績} = 26.59 + 0.57 \times \text{出席率} + 5.06 \times \text{学習時間} + \text{誤差}\) として作っています。


コードを表示
viewof rhoOV = Inputs.range([-0.8, 0.8], {step: 0.05, value: 0.6, label: "出席率と学習時間の相関"})
viewof goOV = Inputs.button("データを作り直す")


















コードを表示
ovSim = {
  goOV;
  const n = 100, b0 = 26.59, b1 = 0.57, b2 = 5.06;
  const randn = () =&gt; {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const rows = [];
  for (let i = 0; i &lt; n; i++) {
    const z1 = randn(), z2 = randn();
    const t = 10.6 + 5.78 * z1;
    const att = 79.9 + 11.23 * (rhoOV * z1 + Math.sqrt(1 - rhoOV ** 2) * z2);
    const y = b0 + b1 * att + b2 * t + 9.34 * randn();
    rows.push({att, t, y});
  }
  const ma = d3.mean(rows, d =&gt; d.att), mt = d3.mean(rows, d =&gt; d.t), my = d3.mean(rows, d =&gt; d.y);
  const saa = d3.sum(rows, d =&gt; (d.att - ma) ** 2);
  const stt = d3.sum(rows, d =&gt; (d.t - mt) ** 2);
  const sat = d3.sum(rows, d =&gt; (d.att - ma) * (d.t - mt));
  const say = d3.sum(rows, d =&gt; (d.att - ma) * (d.y - my));
  const sty = d3.sum(rows, d =&gt; (d.t - mt) * (d.y - my));
  // 単回帰分析（成績を出席率で回帰）
  const bS = say / saa, aS = my - bS * ma;
  const sseS = d3.sum(rows, d =&gt; (d.y - aS - bS * d.att) ** 2);
  const seS = Math.sqrt(sseS / (n - 2) / saa);
  // 重回帰分析（成績を出席率と学習時間で回帰）
  const det = saa * stt - sat * sat;
  const bM1 = (say * stt - sty * sat) / det;
  const bM2 = (sty * saa - say * sat) / det;
  const aM = my - bM1 * ma - bM2 * mt;
  const sseM = d3.sum(rows, d =&gt; (d.y - aM - bM1 * d.att - bM2 * d.t) ** 2);
  const seM1 = Math.sqrt(sseM / (n - 3) * stt / det);
  const r = sat / Math.sqrt(saa * stt);
  return {rows, bS, seS, bM1, seM1, bM2, r};
}

