24.16 ダミー変数と交差項を確かめよう
男性と女性の「本当の切片の差」と「本当の傾きの差」を決めて、100人分のデータ（勉強時間と点数）を作り、「ダミー変数のみ」と「交差項あり」の2つの方法で分析してみましょう。


コードを表示
viewof gapD = Inputs.range([-20, 20], {step: 1, value: 10, label: "本当の切片の差"})
viewof slopeD = Inputs.range([-2, 2], {step: 0.1, value: 1, label: "本当の傾きの差"})
viewof modelD = Inputs.radio(["ダミー変数のみ", "交差項あり"], {value: "ダミー変数のみ", label: "分析の方法"})
viewof goD = Inputs.button("データを作り直す")
































コードを表示
dumData = {
  goD;
  const randn = () =&gt; {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  return Array.from({length: 100}, () =&gt; {
    const x = Math.random() * 20;
    const f = Math.random() &lt; 0.5 ? 1 : 0;
    const y = 40 + 2 * x + gapD * f + slopeD * x * f + 6 * randn();
    return {x, f, y, sex: f === 1 ? "女性" : "男性"};
  });
}

dumFit = {
  // 最小二乗法（正規方程式をガウスの消去法で解く）
  const cols = modelD === "交差項あり"
    ? [d =&gt; 1, d =&gt; d.x, d =&gt; d.f, d =&gt; d.x * d.f]
    : [d =&gt; 1, d =&gt; d.x, d =&gt; d.f];
  const k = cols.length;
  const A = Array.from({length: k}, (_, i) =&gt;
    Array.from({length: k}, (_, j) =&gt; d3.sum(dumData, d =&gt; cols[i](d) * cols[j](d))));
  const bvec = Array.from({length: k}, (_, i) =&gt; d3.sum(dumData, d =&gt; cols[i](d) * d.y));
  for (let i = 0; i &lt; k; i++) {
    for (let r = i + 1; r &lt; k; r++) {
      const m = A[r][i] / A[i][i];
      for (let c = i; c &lt; k; c++) A[r][c] -= m * A[i][c];
      bvec[r] -= m * bvec[i];
    }
  }
  const coef = new Array(k).fill(0);
  for (let i = k - 1; i &gt;= 0; i--) {
    let s = bvec[i];
    for (let c = i + 1; c &lt; k; c++) s -= A[i][c] * coef[c];
    coef[i] = s / A[i][i];
  }
  const [a, b1, b2, b3 = 0] = coef;
  return {a, b1, b2, b3};
}

